<div class="section-title"><div><h1>Review claims</h1><p class="muted">AI scores are supporting information only. Review ownership evidence before deciding.</p></div></div>
<div class="card" style="margin-bottom:20px"><a href="?status=pending">Pending</a> · <a href="?status=approved">Approved</a> · <a href="?status=rejected">Rejected</a> · <a href="?status=all">All</a></div>
<?php if(!$claims):?><div class="card empty">No claims in this view.</div><?php else:?><div class="grid-2"><?php foreach($claims as $claim):?><article class="card"><div class="meta"><?= status_badge($claim['status']) ?><span><?= h($claim['created_at']) ?></span></div><h2><?= h($claim['found_title']) ?></h2><p><strong>Claimant:</strong> <?= h($claim['claimant_name']) ?> (<?= h($claim['claimant_email']) ?>)</p><p><strong>Related lost report:</strong> <a href="<?= h(url('item.php?id='.$claim['lost_item_id'])) ?>"><?= h($claim['lost_title']) ?></a></p><p><strong>Evidence:</strong><br><?= nl2br(h($claim['evidence'])) ?></p><?php if($claim['status']==='pending'):?><form method="post" action="<?= h(url('admin/claim_action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="claim_id" value="<?= (int)$claim['id'] ?>"><div class="form-group"><label for="notes-<?= (int)$claim['id'] ?>">Administrator notes</label><textarea id="notes-<?= (int)$claim['id'] ?>" name="admin_notes" required></textarea></div><div class="form-actions"><button class="btn btn-success" name="decision" value="approved">Approve</button><button class="btn btn-danger" name="decision" value="rejected">Reject</button></div></form><?php else:?><p><strong>Decision note:</strong> <?= h($claim['admin_notes'] ?: '—') ?></p><?php endif;?></article><?php endforeach;?></div><?php endif;?>
